"""NGINX foundations, configuration, proxying, security and operations."""
from ._catalog import build_guided_catalog

ANALOGY = "NGINX is a traffic desk at the edge of an application: it reads each request, applies ordered routing rules, and serves or forwards the request to the right destination."
CATEGORIES = [
    {"id": "architecture", "title": "Architecture & Request Flow", "color": "sky", "blurb": "Understand workers, contexts, request phases and configuration inheritance."},
    {"id": "configuration", "title": "Configuration & Static Content", "color": "mint", "blurb": "Build predictable server blocks, locations, paths and response behavior."},
    {"id": "proxy", "title": "Reverse Proxy & Load Balancing", "color": "peach", "blurb": "Forward traffic safely to applications and upstream pools."},
    {"id": "security", "title": "TLS, Security & Caching", "color": "lilac", "blurb": "Protect connections, control request handling and cache deliberately."},
    {"id": "operations", "title": "Operations & Troubleshooting", "color": "rose", "blurb": "Validate changes, observe behavior and recover safely."},
]

_ROWS = [
    # Architecture & request flow
    ("How NGINX Works", "architecture", "basic", "NGINX accepts a connection, parses the HTTP request, selects a server and location, then serves a file or passes work to an upstream. Its event-driven workers can manage many mostly idle connections without one thread per client.", "worker_processes auto;\nevents { worker_connections 1024; }\nhttp { server { listen 8080; location / { return 200 'hello'; } } }"),
    ("Master and Worker Processes", "architecture", "basic", "The master reads configuration and manages worker processes. Workers handle client connections; keeping request work nonblocking lets each worker serve many concurrent clients.", "ps -o pid,ppid,comm -C nginx"),
    ("Worker Connections and Capacity", "architecture", "intermediate", "worker_connections limits simultaneous connections handled by each worker, not a direct count of users. Upstream and client connections both consume capacity, and OS file descriptor limits also apply.", "worker_processes auto;\nevents { worker_connections 2048; }"),
    ("Configuration Contexts", "architecture", "basic", "Directives belong to contexts such as main, events, http, server and location. A directive is valid only in its supported contexts, so placing it at the wrong level produces a configuration error.", "http {\n  server {\n    location / {\n      root /srv/www;\n    }\n  }\n}"),
    ("Configuration Inheritance", "architecture", "intermediate", "Some directives inherit from a parent context when not redefined, while others append or replace values. Verify the effective configuration instead of assuming all child blocks merge the same way.", "http {\n  access_log /var/log/nginx/access.log;\n  server {\n    access_log off;\n  }\n}"),
    ("Request Processing Phases", "architecture", "advanced", "NGINX processes a request through phases that include URI selection, access checks, content generation and logging. Rewrites and internal redirects can restart location selection, so loops and ordering need attention.", "location /legacy/ {\n  rewrite ^/legacy/(.*)$ /new/$1 last;\n}\nlocation /new/ { root /srv/www; }"),
    ("HTTP and Stream Modules", "architecture", "intermediate", "The http context handles HTTP application traffic, while stream handles generic TCP or UDP proxying. Use the protocol-specific module so HTTP headers and paths are available only where they make sense.", "stream {\n  upstream database { server db.internal:5432; }\n  server { listen 5432; proxy_pass database; }\n}"),
    ("Build and Module Availability", "architecture", "intermediate", "NGINX capabilities depend on compiled or dynamically loaded modules and the package build. Check nginx -V and module documentation before designing a configuration around a feature.", "nginx -V 2>&1"),
    ("DNS Resolution for Upstreams", "architecture", "advanced", "A hostname in an upstream can be resolved when configuration loads, while dynamic resolution depends on version, resolver settings and configuration form. DNS TTL and stale addresses affect how quickly a changed target is used.", "resolver 10.0.0.2 valid=30s;\nresolver_timeout 5s;"),
    ("Graceful Reload and Worker Replacement", "architecture", "intermediate", "A reload validates and applies new configuration while old workers finish existing connections. Long-lived requests can keep old workers alive, so monitor worker shutdown and use a deliberate graceful timeout.", "nginx -t && nginx -s reload"),
    # Configuration and static files
    ("Minimal Server Block", "configuration", "basic", "A server block binds a listener to a hostname and defines how matching requests are handled. Keep the default server explicit so unknown hostnames do not accidentally reach a sensitive site.", "server {\n  listen 80;\n  server_name example.test;\n  location / { return 200 'ready'; }\n}"),
    ("Listen and Default Server Selection", "configuration", "basic", "NGINX first matches the destination address and port, then compares the Host header with server_name values. The default_server handles unmatched hostnames on that listener.", "server { listen 80 default_server; server_name _; return 444; }"),
    ("Exact, Prefix and Regex Locations", "configuration", "intermediate", "Location selection considers exact matches, longest prefixes and regular expressions according to NGINX precedence rules. An exact location wins first; regex order and the ^~ modifier can change which handler is chosen.", "location = /health { return 200 'ok'; }\nlocation ^~ /assets/ { root /srv/www; }"),
    ("Root, Alias and URI to File Mapping", "configuration", "basic", "root appends the request URI to a filesystem path, while alias replaces the matched location prefix. A path that looks similar can map to a different file, so test the resolved path carefully.", "location /images/ { alias /srv/media/; }"),
    ("Index Files and Directory Requests", "configuration", "basic", "The index directive lists files to try for a directory URI. NGINX may internally redirect to a candidate path, which is then processed again through location matching.", "location / { root /srv/site; index index.html index.htm; }"),
    ("try_files and Fallback Routing", "configuration", "intermediate", "try_files checks candidate files in order and can route missing paths to a named location or URI. This is common for single-page apps, but API paths should usually keep a real 404 response.", "location / { root /srv/site; try_files $uri $uri/ /index.html; }"),
    ("Named Locations and Internal Redirects", "configuration", "advanced", "Named locations provide an internal destination for directives such as try_files and error_page. They avoid exposing an internal handler as a public URI and make fallback flows explicit.", "location / { try_files $uri @app; }\nlocation @app { proxy_pass http://app; }"),
    ("URI Rewrite and Redirect Choices", "configuration", "intermediate", "rewrite changes the URI used in request processing, while return sends a response directly and can create an external redirect. Prefer a direct return when no internal routing step is needed.", "location = /old { return 301 /new; }"),
    ("Custom Error Pages", "configuration", "intermediate", "error_page maps selected status codes to an error response or internal URI. Keep API error bodies predictable and avoid returning detailed filesystem or backend diagnostics to clients.", "error_page 404 /404.html;\nlocation = /404.html { internal; root /srv/errors; }"),
    ("MIME Types and Content-Type", "configuration", "basic", "The types map file extensions to response MIME types. A missing mapping can cause browser downloads or incorrect rendering, while a catch-all default type should be chosen deliberately.", "include /etc/nginx/mime.types;\ndefault_type application/octet-stream;"),
    # Proxying and load balancing
    ("Reverse Proxy Basics", "proxy", "basic", "A reverse proxy accepts a client request and makes a separate request to an application server. NGINX returns the upstream response to the client and can centralize routing, TLS and access policy.", "location / { proxy_pass http://app_pool; }"),
    ("Forwarding Host and Client Headers", "proxy", "basic", "An upstream needs the original host and client address when application behavior or auditing depends on them. Forwarded headers are only trustworthy when the application trusts the proxy boundary and strips spoofed client values.", "proxy_set_header Host $host;\nproxy_set_header X-Real-IP $remote_addr;\nproxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;"),
    ("proxy_pass URI Semantics", "proxy", "intermediate", "A proxy_pass URL with or without a URI suffix changes how a matched location prefix is replaced upstream. Check the resulting upstream path with both a matching and a nonmatching URI.", "location /api/ { proxy_pass http://app/; }"),
    ("Upstream Groups", "proxy", "basic", "An upstream group names application servers and lets proxy_pass target the group. Keep discovery, health behavior and connection limits aligned with how the application instances are deployed.", "upstream app_pool { server 10.0.1.10:8080; server 10.0.1.11:8080; }"),
    ("Round Robin and Least Connections", "proxy", "intermediate", "Round robin distributes new requests across upstream servers by default. least_conn can favor servers with fewer active connections, which may help when request durations vary substantially.", "upstream app_pool { least_conn; server app1:8080; server app2:8080; }"),
    ("Weighted Upstream Servers", "proxy", "intermediate", "Weights assign a relative share of traffic among available upstream servers. A weight can support gradual capacity balancing, but it does not replace health checks or a canary rollout plan.", "upstream app_pool { server app1:8080 weight=3; server app2:8080 weight=1; }"),
    ("Passive Failure Handling", "proxy", "intermediate", "NGINX can temporarily mark an upstream unavailable after configured failures within a time window. This is passive observation of requests, not a complete active health check for every deployment.", "upstream app_pool { server app1:8080 max_fails=3 fail_timeout=20s; }"),
    ("Connection and Response Timeouts", "proxy", "basic", "Proxy timeouts bound how long connection establishment, writes and reads can take. A read timeout is an inactivity interval between upstream reads, not a guaranteed total request deadline.", "proxy_connect_timeout 3s;\nproxy_send_timeout 30s;\nproxy_read_timeout 30s;"),
    ("WebSocket Upgrade Proxying", "proxy", "intermediate", "WebSocket begins as an HTTP upgrade and then keeps a connection open. Forward the Upgrade and Connection headers and tune idle timeouts for expected connection duration.", "proxy_http_version 1.1;\nproxy_set_header Upgrade $http_upgrade;\nproxy_set_header Connection $connection_upgrade;"),
    ("Buffering and Streaming Responses", "proxy", "advanced", "Proxy buffering can absorb upstream bursts and release client data at a suitable pace. Disable or adjust it for streaming endpoints only after understanding memory, disk and slow-client effects.", "location /events/ { proxy_buffering off; proxy_read_timeout 1h; }"),
    # TLS and security
    ("TLS Termination", "security", "basic", "TLS termination decrypts HTTPS at NGINX so it can inspect HTTP routing and forward traffic onward. Decide whether the internal hop also needs encryption based on network trust and compliance requirements.", "server { listen 443 ssl; server_name example.test; ssl_certificate /etc/ssl/site.crt; ssl_certificate_key /etc/ssl/site.key; }"),
    ("Certificate Chain and Private Key", "security", "basic", "The certificate file should present the server certificate with the needed intermediate chain, and the private key must match it. Protect key permissions and verify the certificate name and expiry before deployment.", "openssl x509 -in /etc/ssl/site.crt -noout -subject -issuer -dates"),
    ("TLS Protocols and Cipher Policy", "security", "intermediate", "TLS protocol and cipher choices balance client compatibility with current cryptographic practice. Use a maintained policy appropriate to the deployment and verify it with an external TLS checker.", "ssl_protocols TLSv1.2 TLSv1.3;"),
    ("HTTP to HTTPS Redirect", "security", "basic", "A dedicated HTTP listener can redirect public requests to HTTPS. Confirm proxy or load balancer topology so redirects use the original scheme and do not create loops.", "server { listen 80; server_name example.test; return 301 https://$host$request_uri; }"),
    ("Security Headers", "security", "intermediate", "Response headers can set browser protections such as content security policy and content type handling. Choose values that fit the application; a strict policy copied blindly can break legitimate scripts or embeds.", "add_header X-Content-Type-Options nosniff always;\nadd_header Referrer-Policy strict-origin-when-cross-origin always;"),
    ("Request Body and Header Limits", "security", "intermediate", "Request size and header limits constrain resource use and reject malformed or oversized input early. Coordinate limits with application upload rules and expected identity-provider headers.", "client_max_body_size 10m;\nclient_header_timeout 10s;"),
    ("Access Control by Address", "security", "intermediate", "allow and deny rules can restrict a location by client address. Behind another proxy, remote_addr may be the proxy itself; trust real client addresses only from known proxy networks.", "location /internal/ { allow 10.20.0.0/16; deny all; }"),
    ("Basic Authentication and Authorization Boundaries", "security", "intermediate", "NGINX basic auth can gate a location, but it does not replace application authorization. Use HTTPS, protect the password file, and keep identity and permission decisions in the system that owns them.", "location /admin/ { auth_basic 'Restricted'; auth_basic_user_file /etc/nginx/htpasswd; }"),
    ("Rate Limiting Requests", "security", "advanced", "The limit_req module tracks request rates by a chosen key and can delay or reject bursts. Choose a key that represents a client fairly and account for shared NAT addresses and trusted proxy headers.", "limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;\nlocation /api/ { limit_req zone=api burst=20 nodelay; }"),
    ("Proxy Cache Keys and Bypass", "security", "advanced", "A cache key defines which requests share a cached response. Include relevant variation such as host and URI, and bypass cache for authenticated or personalized responses to prevent cross-user leaks.", "proxy_cache_key '$scheme$request_method$host$request_uri';\nproxy_cache_bypass $http_authorization;"),
    ("Compression and Cache-Control", "security", "intermediate", "Compression can reduce transfer size at CPU cost, while cache-control controls client and intermediary reuse. Exclude unsuitable content and avoid caching private responses as public assets.", "gzip on;\ngzip_types text/plain text/css application/javascript application/json;"),
    # Operations and troubleshooting
    ("Validate Before Reload", "operations", "basic", "nginx -t parses the configuration and checks referenced files before a reload. Validation reduces syntax mistakes but cannot prove the route, certificate or upstream behaves correctly at runtime.", "nginx -t && nginx -s reload"),
    ("Access and Error Logs", "operations", "basic", "Access logs describe completed requests and error logs report processing problems. Include fields useful for correlation while avoiding secrets, tokens and personal data in logs.", "access_log /var/log/nginx/access.log;\nerror_log /var/log/nginx/error.log warn;"),
    ("Custom Log Formats and Request IDs", "operations", "intermediate", "A custom access log format can record request duration, upstream status and a correlation identifier. Ensure the identifier is generated or validated at a trusted boundary before using it to join logs.", "log_format upstream '$request_id $status $request_time $upstream_addr $upstream_status';\naccess_log /var/log/nginx/access.log upstream;"),
    ("Upstream Status and Timing", "operations", "intermediate", "Upstream address, status and timing fields help distinguish edge latency from application latency. Missing upstream values may mean the request was answered directly or failed before proxying.", "$upstream_addr $upstream_status $upstream_response_time"),
    ("Health Endpoints", "operations", "basic", "A health endpoint should be cheap, intentional and distinguish process liveness from application readiness when necessary. Restrict sensitive diagnostic details and monitor the same path users depend on.", "location = /healthz { access_log off; add_header Content-Type text/plain; return 200 'ok'; }"),
    ("Debug a 502 Bad Gateway", "operations", "basic", "A 502 commonly means NGINX could not establish or use a valid upstream response. Check upstream DNS, reachability, application listeners, protocol mismatch and the exact error log message.", "curl -sv http://127.0.0.1:8080/health\ntail -n 50 /var/log/nginx/error.log"),
    ("Debug a 504 Gateway Timeout", "operations", "intermediate", "A 504 indicates an upstream operation exceeded a configured timeout or did not respond in time. Measure application latency and dependency waits before raising the timeout, which can increase resource occupancy.", "grep 'upstream timed out' /var/log/nginx/error.log"),
    ("File Permissions and SELinux", "operations", "intermediate", "The NGINX worker identity needs read access to content and certificates, while operating-system security policy may also deny access. Diagnose the effective process user and audit logs rather than applying broad permissions.", "ps -eo user,pid,comm | grep '[n]ginx'\nnamei -l /srv/www/index.html"),
    ("Container Networking and Listen Addresses", "operations", "intermediate", "Inside a container, binding to loopback exposes a service only inside that container. Bind to the intended interface and publish the port through the platform network policy and service mapping.", "server { listen 0.0.0.0:8080; }"),
    ("Zero Downtime Deployment Patterns", "operations", "advanced", "A rolling or blue-green deployment can switch upstream traffic between old and new application versions. Drain connections, check readiness and keep a fast rollback target before removing the prior version.", "upstream app_pool { server app-v2:8080; server app-v1:8080 backup; }"),
    ("Metrics and Status Exposure", "operations", "advanced", "Operational metrics help reveal connection saturation and request pressure. If an NGINX status endpoint is enabled, bind it to a protected internal path and expose only the minimum needed metrics.", "location = /nginx_status { stub_status; allow 127.0.0.1; deny all; }"),
    ("Safe Configuration Rollback", "operations", "intermediate", "Keep a known-good configuration revision and a tested reload procedure. If a change passes syntax validation but harms traffic, restore the prior revision and reload while checking logs and request behavior.", "cp /etc/nginx/nginx.conf /etc/nginx/nginx.conf.previous\nnginx -t && nginx -s reload"),
]

